/* Data model for the CityLord map (Battle of Agents, scene map3.unity).
 * The table contents live in citylord_data.c, generated by tools/gen_scene_c.py. */
#ifndef CITYLORD_DATA_H
#define CITYLORD_DATA_H

#define CL_MAX_RENDERER_MATERIALS 8

typedef enum {
    CL_SHADER_MOBILE_DIFFUSE = 0,        /* "Mobile/Diffuse": Lambert, albedo = _MainTex only (ignores _Color) */
    CL_SHADER_LEGACY_CUTOUT_DIFFUSE = 1, /* "Legacy Shaders/Transparent/Cutout/Diffuse": Lambert, tex*_Color, clip(a-_Cutoff) */
    CL_SHADER_STANDARD = 2,              /* "Standard" (metallic workflow) */
    CL_SHADER_SKYBOX_6SIDED = 3          /* "Skybox/6 Sided" */
} CL_ShaderKind;

typedef enum { CL_COLLIDER_BOX = 0, CL_COLLIDER_MESH = 1 } CL_ColliderKind;

typedef struct {
    const char *file;   /* relative to the assets folder */
    const char *name;
    int width, height;
    int filter_mode;    /* 0 point, 1 bilinear, 2 trilinear */
    int aniso;
    int wrap_u, wrap_v; /* 0 repeat, 1 clamp */
    float mip_bias;
} CL_Texture;

typedef struct {
    const char *file;
    const char *name;
    int vertex_count;
    int submesh_count;
} CL_MeshInfo;

typedef struct {
    const char *name;
    CL_ShaderKind shader;
    int render_queue;
    float color[4];
    int main_tex; float main_st[4]; /* tiling.xy, offset.xy */
    float cutoff;
    int bump_tex; float bump_st[4]; float bump_scale; int normalmap;
    int metal_tex; float metallic, glossiness, gloss_map_scale; int metalgloss, smoothness_channel;
    int occlusion_tex; float occlusion_strength;
    float emission[4]; int emission_tex;
    int specular_highlights, glossy_reflections;
    int sky_tex[6];     /* front, back, left, right, up, down */
    float tint[4]; float exposure, rotation;
} CL_Material;

typedef struct {
    const char *path;     /* GameObject path in the Unity hierarchy */
    int mesh;             /* index into cl_meshes */
    int first_submesh;    /* static batching: submesh range inside the combined mesh */
    int submesh_count;
    int static_batched;   /* 1: vertices already in world space, draw with identity */
    int material_count;
    int materials[CL_MAX_RENDERER_MATERIALS];
    float world[16];      /* column-major localToWorld (Unity space) */
    int cast_shadows, receive_shadows;
    int layer;
} CL_Renderer;

typedef struct {
    const char *path;
    CL_ColliderKind kind;
    float world[16];
    float center[3], size[3]; /* box collider */
    int mesh;                 /* mesh collider */
    int is_trigger;
    int layer;
} CL_Collider;

typedef struct {
    float light_rotation[4];
    float light_color[4];
    float light_intensity;
    int light_shadows; /* 0 none, 1 hard, 2 soft */
    float shadow_strength, shadow_bias, shadow_normal_bias;
    int ambient_mode;  /* 0 skybox, 1 trilight, 3 flat */
    float ambient_sky[4], ambient_equator[4], ambient_ground[4];
    float ambient_intensity;
    int fog, fog_mode;
    float fog_color[4];
    float fog_density, fog_start, fog_end;
    int skybox_material;
    float camera_position[3], camera_rotation[4];
    float camera_fov, camera_near, camera_far;
    float camera_background[4];
} CL_SceneSettings;

extern const CL_Texture cl_textures[];
extern const int cl_texture_count;
extern const CL_MeshInfo cl_meshes[];
extern const int cl_mesh_count;
extern const CL_Material cl_materials[];
extern const int cl_material_count;
extern const CL_Renderer cl_renderers[];
extern const int cl_renderer_count;
extern const CL_Collider cl_colliders[];
extern const int cl_collider_count;
extern const CL_SceneSettings cl_settings;

#endif
